import {passiveHealth,passiveHealthEvidence,PASSIVE_HEALTH} from './expedition-passive-training.mjs';
// Historical CON/CHA standard-defence structure; skill/encounters/costs are prototype content.
export const DISEASE_RULE='疾病使用自然耐病：2×当前体质＋当前魅力，再加当前全防御加成；不使用心智抵抗、闪身或盾牌格挡，不扣防御法力。沿本项目既有非心理伤害政策使用物理护甲及疾病抗性；不借用法术抗性，不触发物理援护。不附持续感染或永久伤势，普通治疗仍可恢复本次失去的生命。';
export const SPORES={name:'孢潮喷散',kind:'attack',type:'disease',primary:'int',secondary:'con',power:.8,cost:4,item:'herb',mode:'all',max:6,desc:'公开敌方技能，4法力/1份敌方药草、至多6名存活敌对单位，逐人独立疾病攻防；只支付一次。自然耐病采用体质/魅力，防御免费，物理护甲依原非心理规则参与，法术抗性不代替疾病抗性。无持续感染、没有额外玩家课程；技能及参数为项目改编。'};
const row=(skill,target='front')=>({skill,target,mode:'repeat'}),attrs={str:12,con:16,int:18,dex:12,cha:8,agi:12,per:12,wil:14};
const foe=(id,name,pos,hp,skills)=>({id,name,pos,mark:'孢',side:'enemy',gear:'field',attrs:{...attrs},hp,maxHp:hp,mp:80,maxMp:80,skills,defenses:{melee:'natural',ranged:'natural',magic:'natural'},prep:[],main:[row(Object.keys(skills)[0],Object.hasOwn(skills,'spores')?'all':'front')],healing:{enabled:false}});
export const SPORE_ROOMS=[{id:'spore-entry',name:'01 · 散孢药圃',note:'前排药圃守卫阻拦近战，后排散孢花簇用疾病攻击全队至多6人。耐病看体质/魅力和当前防御加成，选择心智抵抗不能替代；治疗、按阵位护印或先拆花簇各占原行动和材料。',enemies:[foe('sgg','药圃守卫','front',150,{strike:8}),foe('sgp','散孢花簇','rear',180,{spores:8})]},{id:'spore-heart',name:'02 · 孢潮根庭',note:'生命与法力延续。孢潮母株会先用守势保护自己，再向全队散孢，前排药径护卫仍用普通剑术。护印一次只护所选阵位最多3人，不能把分散的6人都算作覆盖；疾病不是可净化的潮蚀状态。',enemies:[foe('shg','药径护卫','front',180,{strike:9}),{...foe('shp','孢潮母株','rear',240,{spores:10,guard:6}),prep:[row('guard','self')]}]}];
export function diseaseDefense(unit,current,hasRanks=false){const primary='con',secondary='cha',a=current(unit,primary),b=current(unit,secondary),base=2*a+b,passive=passiveHealth(unit),generalDefenseBonus=current(unit,'defense'),bonus=generalDefenseBonus+(passive?.amount||0);return {requested:'natural',skill:'natural',name:'自然耐病',reason:null,level:0,training:0,specialization:0,...(hasRanks?{equipment:0}:{}),temporaryLevel:0,cost:0,primary,secondary,primaryValue:a,secondaryValue:b,base,bonus,mean:base+bonus,...(passive?{passiveTraining:{...passive,generalDefenseBonus}}:{}),diseaseRule:passive?DISEASE_RULE+' 已培养耐病修习按永久等级每级另加4均值，包含在合计加值；不耗行动、法力或材料。':DISEASE_RULE};}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function diseaseEvidenceView(group){const events=group?.events||[group],hits=events.filter(e=>e?.type==='attack'&&e.detail.attackType==='disease'),d=events.find(e=>e?.type==='defend'&&e.detail.attackType==='disease');if(!hits.length&&!d)return '';return `<section class=disease-proof><h3>疾病攻防 · 当前体质与魅力</h3><p>${esc(DISEASE_RULE)}</p>${hits.map(e=>{const p=e.detail.defenseProfile;return `<p data-disease-hit="${esc(e.id)}">${esc(e.units?.find(u=>u.id===e.targets[0])?.name||'受击者')}：体质${esc(p.primaryValue)}×2＋魅力${esc(p.secondaryValue)}${passiveHealthEvidence(p)?`＋全防御${esc(p.passiveTraining.generalDefenseBonus)}＋${PASSIVE_HEALTH.name}${esc(p.passiveTraining.amount)}（已培养${esc(p.passiveTraining.rank)}级，无需指令）`:Object.hasOwn(p,'passiveTraining')?'＋追加来源不可用；合计加值'+esc(p.bonus):'＋全防御'+esc(p.bonus)}＝均值${esc(p.mean)}；实掷${esc(e.detail.defense)}，防御耗蓝${esc(p.cost)}；护甲${esc(e.detail.armor)}，疾病抗性${esc(e.detail.resistance)}%，实伤${esc(e.detail.actual)}。</p>`;}).join('')}</section>`;}
export function diseasePreparationView(config){return config.expedition==='sporegrove'?`<section id=disease-planning class=panel><h3>自然耐病 · 体质与魅力的职责</h3><p>${esc(DISEASE_RULE)}</p><p>屏障与守势仍只对真正覆盖者提高检定；当前三项防御选择继续服务近战、远程、法术/心理，疾病不另加选择栏。具体遭遇/费用和保留护甲的政策为项目改编，未核实现行服务器数字。</p></section>`:'';}
